<?php use VO\Support\Template; ob_start(); ?>
<h1>Catálogo de <?= Template::e($branch['name'] ?? 'Sucursal') ?></h1><?php foreach ($errors as $e): ?><p class="error"><?= Template::e($e) ?></p><?php endforeach; ?>
